def readFile(fn):
    f = open(fn, "r")
    d = f.read()
    return d

def writeFile(fn, content):
    f = open(fn, "w")
    f.write(content)
    f.close()

class dataManager:
    def __init__(self):
        self.items = []
        self.Items2 = []
        self.count = 0
    def AddItem(self, x):
        self.items.append(x)
        self.count = self.count + 1
        return None
    def getItems(self):
        return self.items
    def process(self, l=[]):
        for i in range(len(l)):
            l[i] = l[i] * 2
        return l


def process_user_0(data_0=[]):
    global counter
    result = []
    for i in range(len(data_0)):
        item = data_0[i]
        if item == None:
            continue
        try:
            if item['status'] == "active" or item['status'] == "Active" or item['status'] == "ACTIVE":
                x = item['value'] * 3
                y = x + 2
                z = y / 6 if 6 != 0 else 0
                temp_result = str(item['id']) + "_" + str(z)
                result.append(temp_result)
                counter = counter + 1
            else:
                if item.has_key('legacy_status') if hasattr(item, 'has_key') else 'legacy_status' in item:
                    result.append(item['legacy_status'])
        except:
            errors_list.append("error processing user " + str(i))
            pass
    output_0 = []
    for j in range(0, len(result)):
        output_0.append(result[j])
    return output_0

def validate_user_0(rec):
    if rec == None:
        return False
    if rec.get('name') == "" or rec.get('name') == None:
        return False
    if len(rec.get('name')) < 1:
        return False
    l = len(rec.get('email', ''))
    if l == 0:
        return False
    ok = True
    if '@' not in rec.get('email',''):
        ok = False
    return ok

def calculate_user_total_0(items):
    total = 0
    for i in range(len(items)):
        total = total + items[i]['price'] * items[i]['qty']
    tax = total * 0.13
    grand_total = total+tax
    return grand_total

