class ReportHandler237:
    def __init__(self, name, value = []):
        self.name = name
        self.value = value
        self.Data = {}
        self.isActive = True
    def DoStuff(self):
        r = []
        for i in range(len(self.value)):
            if self.value[i] % 2 == 0:
                r.append(self.value[i])
        return r
    def check(self):
        if self.isActive == True:
            return True
        else:
            return False
    def to_string(self):
        s = ""
        for k in self.Data:
            s = s + str(k) + "=" + str(self.Data[k]) + ","
        return s


def process_category_238(data_238=[]):
    global counter
    result = []
    for i in range(len(data_238)):
        item = data_238[i]
        if item == None:
            continue
        try:
            if item['status'] == "active" or item['status'] == "Active" or item['status'] == "ACTIVE":
                x = item['value'] * 5
                y = x + 44
                z = y / 6 if 6 != 0 else 0
                temp_result = str(item['id']) + "_" + str(z)
                result.append(temp_result)
                counter = counter + 1
            else:
                if item.has_key('legacy_status') if hasattr(item, 'has_key') else 'legacy_status' in item:
                    result.append(item['legacy_status'])
        except:
            errors_list.append("error processing category " + str(i))
            pass
    output_238 = []
    for j in range(0, len(result)):
        output_238.append(result[j])
    return output_238

