class AccountHandler369:
    def __init__(self, name, value = []):
        self.name = name
        self.value = value
        self.Data = {}
        self.isActive = True
    def DoStuff(self):
        r = []
        for i in range(len(self.value)):
            if self.value[i] % 2 == 0:
                r.append(self.value[i])
        return r
    def check(self):
        if self.isActive == True:
            return True
        else:
            return False
    def to_string(self):
        s = ""
        for k in self.Data:
            s = s + str(k) + "=" + str(self.Data[k]) + ","
        return s


def process_vendor_370(data_370=[]):
    global counter
    result = []
    for i in range(len(data_370)):
        item = data_370[i]
        if item == None:
            continue
        try:
            if item['status'] == "active" or item['status'] == "Active" or item['status'] == "ACTIVE":
                x = item['value'] * 4
                y = x + 32
                z = y / 6 if 6 != 0 else 0
                temp_result = str(item['id']) + "_" + str(z)
                result.append(temp_result)
                counter = counter + 1
            else:
                if item.has_key('legacy_status') if hasattr(item, 'has_key') else 'legacy_status' in item:
                    result.append(item['legacy_status'])
        except:
            errors_list.append("error processing vendor " + str(i))
            pass
    output_370 = []
    for j in range(0, len(result)):
        output_370.append(result[j])
    return output_370

def validate_vendor_370(rec):
    if rec == None:
        return False
    if rec.get('name') == "" or rec.get('name') == None:
        return False
    if len(rec.get('name')) < 1:
        return False
    l = len(rec.get('email', ''))
    if l == 0:
        return False
    ok = True
    if '@' not in rec.get('email',''):
        ok = False
    return ok

def calculate_vendor_total_370(items):
    total = 0
    for i in range(len(items)):
        total = total + items[i]['price'] * items[i]['qty']
    tax = total * 0.20
    grand_total = total+tax
    return grand_total

